/* one ops table per object type; the membrane forwards and wraps both ways */
typedef struct obj obj;                     /* opaque handle */
struct membrane { map ids; int revoked; obj *(*wrap)(struct membrane *, obj *); };

obj *membrane_call(struct membrane *m, obj *h, int op, obj *arg) {
    if (m->revoked) return NULL;            /* check and forward in one step */
    obj *w = m->wrap(m, arg);               /* wrap the way in  */
    obj *r = h->ops->call(h->target, op, w);
    return m->wrap(m, r);                   /* wrap the way out */
}
